-- Q1
 SELECT l.l_returnflag, l.l_linestatus, sum(l.l_quantity) AS sum_qty, sum(l.l_extendedprice) AS sum_base_price, sum(l.l_extendedprice * (1 - l.l_discount)) AS sum_disc_price, sum(l.l_extendedprice * (1 - l.l_discount) * (1 + l.l_tax)) AS sum_charge, avg(l.l_quantity) AS avg_qty, avg(l.l_extendedprice) AS avg_price, avg(l.l_discount) AS avg_disc, count(*) AS count_order FROM lineitem l JOIN orders o ON o.o_orderkey = l.l_orderkey AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') JOIN partsupp ps ON ps.ps_partkey = l.l_partkey AND ps.ps_suppkey = l.l_suppkey AND ps.ps_availqty > 100 JOIN supplier s ON s.s_suppkey = ps.ps_suppkey AND s.s_acctbal > 0 JOIN nation n ON n.n_nationkey = s.s_nationkey JOIN region r ON r.r_regionkey = n.n_regionkey AND r.r_name = 'EUROPE' WHERE l.l_shipdate <= date '1998-12-01' - interval '3 days' GROUP BY l.l_returnflag, l.l_linestatus ORDER BY l.l_returnflag, l.l_linestatus 
-- Q2
 SELECT s.s_acctbal, s.s_name, n.n_name, p.p_partkey, p.p_mfgr, s.s_address, s.s_phone, s.s_comment FROM part p JOIN partsupp ps ON ps.ps_partkey = p.p_partkey JOIN supplier s ON s.s_suppkey = ps.ps_suppkey JOIN nation n ON n.n_nationkey = s.s_nationkey JOIN region r ON r.r_regionkey = n.n_regionkey JOIN ( SELECT ps2.ps_partkey, MIN(ps2.ps_supplycost) AS min_supplycost FROM partsupp ps2 JOIN supplier s2 ON s2.s_suppkey = ps2.ps_suppkey JOIN nation n2 ON n2.n_nationkey = s2.s_nationkey JOIN region r2 ON r2.r_regionkey = n2.n_regionkey WHERE r2.r_name = 'EUROPE' AND ps2.ps_availqty > 100 AND s2.s_acctbal > 0 GROUP BY ps2.ps_partkey ) m ON m.ps_partkey = p.p_partkey AND ps.ps_supplycost = m.min_supplycost WHERE p.p_size = 15 AND p.p_type LIKE '%BRASS' AND r.r_name = 'EUROPE' AND s.s_acctbal > 0 AND ps.ps_availqty > 100 ORDER BY s.s_acctbal DESC, n.n_name, s.s_name, p.p_partkey LIMIT 100 
-- Q3
 SELECT l.l_orderkey, SUM(l.l_extendedprice * (1 - l.l_discount)) AS revenue, o.o_orderdate, o.o_shippriority FROM customer c JOIN nation n ON n.n_nationkey = c.c_nationkey JOIN region r ON r.r_regionkey = n.n_regionkey AND r.r_name IN ('EUROPE', 'AMERICA') JOIN orders o ON o.o_custkey = c.c_custkey AND o.o_orderdate < DATE '1995-01-01' AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') JOIN lineitem l ON l.l_orderkey = o.o_orderkey AND l.l_shipdate > DATE '1995-01-01' JOIN partsupp ps ON ps.ps_partkey = l.l_partkey AND ps.ps_suppkey = l.l_suppkey AND ps.ps_availqty > 100 JOIN supplier s ON s.s_suppkey = ps.ps_suppkey AND s.s_acctbal > 0 JOIN nation n2 ON n2.n_nationkey = s.s_nationkey JOIN region r2 ON r2.r_regionkey = n2.n_regionkey AND r2.r_name = 'EUROPE' WHERE c.c_mktsegment = 'FURNITURE' AND c.c_acctbal > 0 GROUP BY l.l_orderkey, o.o_orderdate, o.o_shippriority ORDER BY revenue DESC, o.o_orderdate 
-- Q4
 SELECT o.o_orderpriority, COUNT(*) AS order_count FROM orders o WHERE o.o_orderdate >= DATE '1994-01-01' AND o.o_orderdate < DATE '1994-01-01' + INTERVAL '3 months' AND EXISTS ( SELECT 1 FROM lineitem l JOIN partsupp ps ON ps.ps_partkey = l.l_partkey AND ps.ps_suppkey = l.l_suppkey JOIN supplier s ON s.s_suppkey = ps.ps_suppkey JOIN nation n ON n.n_nationkey = s.s_nationkey JOIN region r ON r.r_regionkey = n.n_regionkey WHERE l.l_orderkey = o.o_orderkey AND l.l_commitdate < l.l_receiptdate AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') AND ps.ps_availqty > 100 AND s.s_acctbal > 0 AND r.r_name = 'EUROPE' ) GROUP BY o.o_orderpriority ORDER BY o.o_orderpriority 
-- Q5
SELECT n_name, sum(l_extendedprice * (1 - l_discount)) AS revenue FROM customer, orders, lineitem, supplier, nation, region WHERE c_custkey = o_custkey AND l_orderkey = o_orderkey AND l_suppkey = s_suppkey AND c_nationkey = s_nationkey AND s_nationkey = n_nationkey AND n_regionkey = r_regionkey AND r_name = 'ASIA' AND o_orderdate >= date '1995-01-01' AND o_orderdate < date '1995-01-01' + interval '1' year AND c_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n2, region r2 WHERE n2.n_nationkey = c_nationkey AND n2.n_regionkey = r2.r_regionkey AND r2.r_name IN ('EUROPE', 'AMERICA') ) AND s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n3, region r3 WHERE n3.n_nationkey = s_nationkey AND n3.n_regionkey = r3.r_regionkey AND r3.r_name = 'EUROPE' ) AND EXISTS ( SELECT 1 FROM orders o2 WHERE o2.o_orderkey = l_orderkey AND o2.o_orderpriority IN ('1-URGENT', '2-HIGH') ) AND EXISTS ( SELECT 1 FROM partsupp ps WHERE ps.ps_partkey = l_partkey AND ps.ps_suppkey = l_suppkey AND ps.ps_availqty > 0 AND ps.ps_availqty > 100 AND EXISTS ( SELECT 1 FROM supplier s2 WHERE s2.s_suppkey = ps.ps_suppkey AND s2.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n4, region r4 WHERE n4.n_nationkey = s2.s_nationkey AND n4.n_regionkey = r4.r_regionkey AND r4.r_name = 'EUROPE' ) ) ) GROUP BY n_name ORDER BY revenue DESC
-- Q6
 SELECT sum(l.l_extendedprice * l.l_discount) AS revenue FROM lineitem l JOIN orders o ON o.o_orderkey = l.l_orderkey AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') JOIN partsupp ps ON ps.ps_partkey = l.l_partkey AND ps.ps_suppkey = l.l_suppkey AND ps.ps_availqty > 100 JOIN supplier s ON s.s_suppkey = ps.ps_suppkey AND s.s_acctbal > 0 JOIN nation n ON n.n_nationkey = s.s_nationkey JOIN region r ON r.r_regionkey = n.n_regionkey AND r.r_name = 'EUROPE' WHERE l.l_shipdate >= DATE '1993-01-01' AND l.l_shipdate < DATE '1995-03-01' AND l.l_discount BETWEEN 0.05 AND 0.07 AND l.l_quantity < 10 
-- Q7
 SELECT n_s.n_name AS supp_nation, n_c.n_name AS cust_nation, EXTRACT(YEAR FROM l.l_shipdate) AS l_year, SUM(l.l_extendedprice * (1 - l.l_discount)) AS revenue FROM lineitem l JOIN orders o ON o.o_orderkey = l.l_orderkey JOIN customer c ON c.c_custkey = o.o_custkey JOIN supplier s ON s.s_suppkey = l.l_suppkey JOIN nation n_s ON n_s.n_nationkey = s.s_nationkey JOIN nation n_c ON n_c.n_nationkey = c.c_nationkey JOIN region r_c ON r_c.r_regionkey = n_c.n_regionkey AND r_c.r_name IN ('EUROPE', 'AMERICA') JOIN region r_s ON r_s.r_regionkey = n_s.n_regionkey AND r_s.r_name = 'EUROPE' JOIN partsupp ps ON ps.ps_partkey = l.l_partkey AND ps.ps_suppkey = l.l_suppkey AND ps.ps_availqty > 100 WHERE ( (n_s.n_name = 'GERMANY' AND n_c.n_name = 'FRANCE') OR (n_s.n_name = 'FRANCE' AND n_c.n_name = 'GERMANY') ) AND l.l_shipdate >= DATE '1995-01-01' AND l.l_shipdate < DATE '1997-01-01' AND c.c_acctbal > 0 AND s.s_acctbal > 0 AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') GROUP BY n_s.n_name, n_c.n_name, EXTRACT(YEAR FROM l.l_shipdate) ORDER BY supp_nation, cust_nation, l_year 
-- Q8
SELECT o_year, sum(CASE WHEN nation = 'INDIA' THEN volume ELSE 0 END) / sum(volume) AS mkt_share FROM ( SELECT extract(year FROM o_orderdate) AS o_year, l_extendedprice * (1 - l_discount) AS volume, n2.n_name AS nation FROM part, supplier, lineitem, orders, customer, nation n1, nation n2, region WHERE p_partkey = l_partkey AND s_suppkey = l_suppkey AND l_orderkey = o_orderkey AND o_custkey = c_custkey AND c_nationkey = n1.n_nationkey AND n1.n_regionkey = r_regionkey AND r_name = 'ASIA' AND s_nationkey = n2.n_nationkey AND o_orderdate BETWEEN date '1995-01-01' AND date '1996-12-31' AND p_type = 'ECONOMY ANODIZED STEEL' AND c_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n3, region r3 WHERE n3.n_nationkey = c_nationkey AND n3.n_regionkey = r3.r_regionkey AND r3.r_name IN ('EUROPE', 'AMERICA') ) AND s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n4, region r4 WHERE n4.n_nationkey = s_nationkey AND n4.n_regionkey = r4.r_regionkey AND r4.r_name = 'EUROPE' ) AND EXISTS ( SELECT 1 FROM orders o2 WHERE o2.o_orderkey = l_orderkey AND o2.o_orderpriority IN ('1-URGENT', '2-HIGH') ) AND EXISTS ( SELECT 1 FROM partsupp ps WHERE ps.ps_partkey = l_partkey AND ps.ps_suppkey = l_suppkey AND ps.ps_availqty > 0 AND ps.ps_availqty > 100 AND EXISTS ( SELECT 1 FROM supplier s2 WHERE s2.s_suppkey = ps.ps_suppkey AND s2.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n5, region r5 WHERE n5.n_nationkey = s2.s_nationkey AND n5.n_regionkey = r5.r_regionkey AND r5.r_name = 'EUROPE' ) ) ) ) AS all_nations GROUP BY o_year ORDER BY o_year
-- Q9
 WITH europe_nations AS ( SELECT n.n_nationkey, n.n_name FROM nation n JOIN region r ON r.r_regionkey = n.n_regionkey WHERE r.r_name = 'EUROPE' ) SELECT n.n_name AS nation, EXTRACT(YEAR FROM o.o_orderdate) AS o_year, SUM(l.l_extendedprice * (1 - l.l_discount) - ps.ps_supplycost * l.l_quantity) AS sum_profit FROM lineitem l JOIN orders o ON o.o_orderkey = l.l_orderkey AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') JOIN partsupp ps ON ps.ps_partkey = l.l_partkey AND ps.ps_suppkey = l.l_suppkey AND ps.ps_availqty > 100 JOIN supplier s ON s.s_suppkey = l.l_suppkey AND s.s_acctbal > 0 JOIN europe_nations n ON n.n_nationkey = s.s_nationkey JOIN part p ON p.p_partkey = l.l_partkey AND p.p_name LIKE 'co%' GROUP BY n.n_name, EXTRACT(YEAR FROM o.o_orderdate) ORDER BY nation, o_year DESC 
-- Q10
 SELECT c.c_custkey, c.c_name, SUM(l.l_extendedprice * (1 - l.l_discount)) AS revenue, c.c_acctbal, n.n_name, c.c_address, c.c_phone, c.c_comment FROM customer c JOIN nation n ON n.n_nationkey = c.c_nationkey JOIN region cr ON cr.r_regionkey = n.n_regionkey AND cr.r_name IN ('EUROPE', 'AMERICA') JOIN orders o ON o.o_custkey = c.c_custkey AND o.o_orderdate >= DATE '1995-01-01' AND o.o_orderdate < DATE '1995-01-01' + INTERVAL '3' month AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') JOIN lineitem l ON l.l_orderkey = o.o_orderkey AND l.l_returnflag = 'R' JOIN partsupp ps ON ps.ps_partkey = l.l_partkey AND ps.ps_suppkey = l.l_suppkey AND ps.ps_availqty > 100 JOIN supplier s ON s.s_suppkey = ps.ps_suppkey AND s.s_acctbal > 0 JOIN nation sn ON sn.n_nationkey = s.s_nationkey JOIN region sr ON sr.r_regionkey = sn.n_regionkey AND sr.r_name = 'EUROPE' WHERE c.c_acctbal > 0 GROUP BY c.c_custkey, c.c_name, c.c_acctbal, c.c_phone, n.n_name, c.c_address, c.c_comment ORDER BY revenue DESC 
-- Q11
SELECT ps_partkey, n_name, SUM(ps_supplycost * ps_availqty) AS total_value FROM partsupp, supplier, nation WHERE ps_suppkey = s_suppkey AND s_nationkey = n_nationkey AND n_name = 'INDIA' AND s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n2, region r2 WHERE n2.n_nationkey = s_nationkey AND n2.n_regionkey = r2.r_regionkey AND r2.r_name = 'EUROPE' ) AND ps_availqty > 100 AND EXISTS ( SELECT 1 FROM supplier s2 WHERE s2.s_suppkey = ps_suppkey AND s2.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n3, region r3 WHERE n3.n_nationkey = s2.s_nationkey AND n3.n_regionkey = r3.r_regionkey AND r3.r_name = 'EUROPE' ) ) GROUP BY ps_partkey, n_name HAVING SUM(ps_supplycost * ps_availqty) > ( SELECT SUM(ps2.ps_supplycost * ps2.ps_availqty) * 0.00001 FROM partsupp ps2, supplier s3, nation n4 WHERE ps2.ps_suppkey = s3.s_suppkey AND s3.s_nationkey = n4.n_nationkey AND n4.n_name = 'INDIA' AND s3.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n5, region r5 WHERE n5.n_nationkey = s3.s_nationkey AND n5.n_regionkey = r5.r_regionkey AND r5.r_name = 'EUROPE' ) AND ps2.ps_availqty > 100 AND EXISTS ( SELECT 1 FROM supplier s4 WHERE s4.s_suppkey = ps2.ps_suppkey AND s4.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n6, region r6 WHERE n6.n_nationkey = s4.s_nationkey AND n6.n_regionkey = r6.r_regionkey AND r6.r_name = 'EUROPE' ) ) ) ORDER BY total_value DESC
-- Q12
 SELECT l_shipmode, sum(CASE WHEN o_orderpriority = '1-URGENT' OR o_orderpriority = '2-HIGH' THEN 1 ELSE 0 END) AS high_line_count, sum(CASE WHEN o_orderpriority <> '1-URGENT' AND o_orderpriority <> '2-HIGH' THEN 1 ELSE 0 END) AS low_line_count FROM orders, lineitem WHERE o_orderkey = l_orderkey AND l_shipmode = 'SHIP' AND l_commitdate < l_receiptdate AND l_shipdate < l_commitdate AND l_receiptdate >= date '1995-01-01' AND l_receiptdate < date '1995-01-01' + interval '1' year AND EXISTS ( SELECT 1 FROM orders o2 WHERE o2.o_orderkey = l_orderkey AND o2.o_orderpriority IN ('1-URGENT', '2-HIGH') ) AND EXISTS ( SELECT 1 FROM partsupp ps WHERE ps.ps_partkey = l_partkey AND ps.ps_suppkey = l_suppkey AND ps.ps_availqty > 100 AND EXISTS ( SELECT 1 FROM supplier s WHERE s.s_suppkey = ps.ps_suppkey AND s.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n, region r WHERE n.n_nationkey = s.s_nationkey AND n.n_regionkey = r.r_regionkey AND r.r_name = 'EUROPE' ) ) ) GROUP BY l_shipmode ORDER BY l_shipmode 
-- Q13
SELECT c_count, c_orderdate, count(*) AS custdist FROM ( SELECT c_custkey, count(o_orderkey), o_orderdate FROM customer LEFT OUTER JOIN orders ON c_custkey = o_custkey AND o_comment NOT LIKE '%special%requests%' WHERE c_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n, region r WHERE n.n_nationkey = c_nationkey AND n.n_regionkey = r.r_regionkey AND r.r_name IN ('EUROPE', 'AMERICA') ) GROUP BY c_custkey, o_orderdate ) AS c_orders (c_custkey, c_count, c_orderdate) GROUP BY c_count, c_orderdate ORDER BY custdist DESC, c_count DESC
-- Q14
 SELECT 100.00 * SUM(l.l_extendedprice * (1 - l.l_discount)) FILTER (WHERE p.p_type LIKE 'PROMO%') / SUM(l.l_extendedprice * (1 - l.l_discount)) AS promo_revenue FROM lineitem l JOIN part p ON p.p_partkey = l.l_partkey JOIN orders o ON o.o_orderkey = l.l_orderkey AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') JOIN partsupp ps ON ps.ps_partkey = l.l_partkey AND ps.ps_suppkey = l.l_suppkey AND ps.ps_availqty > 100 JOIN supplier s ON s.s_suppkey = ps.ps_suppkey AND s.s_acctbal > 0 JOIN nation n ON n.n_nationkey = s.s_nationkey JOIN region r ON r.r_regionkey = n.n_regionkey AND r.r_name = 'EUROPE' WHERE l.l_shipdate >= DATE '1995-01-01' AND l.l_shipdate < DATE '1995-02-01' 
-- Q15
 WITH revenue AS ( SELECT l.l_suppkey AS supplier_no, SUM(l.l_extendedprice * (1 - l.l_discount)) AS total_revenue FROM lineitem l JOIN orders o ON o.o_orderkey = l.l_orderkey AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') JOIN partsupp ps ON ps.ps_partkey = l.l_partkey AND ps.ps_suppkey = l.l_suppkey AND ps.ps_availqty > 100 JOIN supplier s ON s.s_suppkey = l.l_suppkey AND s.s_acctbal > 0 JOIN nation n ON n.n_nationkey = s.s_nationkey JOIN region r ON r.r_regionkey = n.n_regionkey AND r.r_name = 'EUROPE' WHERE l.l_shipdate >= DATE '1995-01-01' AND l.l_shipdate < DATE '1995-01-01' + INTERVAL '3 months' GROUP BY l.l_suppkey ), ranked AS ( SELECT supplier_no, total_revenue, MAX(total_revenue) OVER () AS max_total_revenue FROM revenue ) SELECT s.s_suppkey, s.s_name, s.s_address, s.s_phone, rk.total_revenue FROM ranked rk JOIN supplier s ON s.s_suppkey = rk.supplier_no WHERE rk.total_revenue = rk.max_total_revenue ORDER BY s.s_suppkey 
-- Q16
 WITH europe_suppliers AS ( SELECT s.s_suppkey, s.s_acctbal, s.s_comment FROM supplier s JOIN nation n ON n.n_nationkey = s.s_nationkey JOIN region r ON r.r_regionkey = n.n_regionkey WHERE r.r_name = 'EUROPE' ), eligible_suppliers AS ( SELECT s_suppkey FROM europe_suppliers WHERE s_acctbal > 0 AND s_comment NOT LIKE '%Customer%Complaints%' ) SELECT p.p_brand, p.p_type, p.p_size, COUNT(DISTINCT ps.ps_suppkey) AS supplier_cnt FROM part p JOIN partsupp ps ON ps.ps_partkey = p.p_partkey JOIN eligible_suppliers es ON es.s_suppkey = ps.ps_suppkey WHERE p.p_brand <> 'Brand#23' AND p.p_type NOT LIKE 'MEDIUM POLISHED%' AND p.p_size IN (1, 4, 7) AND ps.ps_availqty > 100 GROUP BY p.p_brand, p.p_type, p.p_size ORDER BY supplier_cnt DESC, p.p_brand, p.p_type, p.p_size 
-- Q17
 SELECT sum(l_extendedprice) / 7.0 AS avg_yearly FROM lineitem, part WHERE p_partkey = l_partkey AND p_brand = 'Brand#53' AND p_container = 'MED BAG' AND l_quantity < ( SELECT 0.7 * avg(l_quantity) FROM lineitem l2 WHERE l2.l_partkey = p_partkey AND EXISTS ( SELECT 1 FROM orders o WHERE o.o_orderkey = l2.l_orderkey AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') ) AND EXISTS ( SELECT 1 FROM partsupp ps WHERE ps.ps_partkey = l2.l_partkey AND ps.ps_suppkey = l2.l_suppkey AND ps.ps_availqty > 100 AND EXISTS ( SELECT 1 FROM supplier s WHERE s.s_suppkey = ps.ps_suppkey AND s.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n, region r WHERE n.n_nationkey = s.s_nationkey AND n.n_regionkey = r.r_regionkey AND r.r_name = 'EUROPE' ) ) ) ) AND EXISTS ( SELECT 1 FROM orders o WHERE o.o_orderkey = l_orderkey AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') ) AND EXISTS ( SELECT 1 FROM partsupp ps WHERE ps.ps_partkey = l_partkey AND ps.ps_suppkey = l_suppkey AND ps.ps_availqty > 100 AND EXISTS ( SELECT 1 FROM supplier s WHERE s.s_suppkey = ps.ps_suppkey AND s.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n, region r WHERE n.n_nationkey = s.s_nationkey AND n.n_regionkey = r.r_regionkey AND r.r_name = 'EUROPE' ) ) ) 
-- Q18
SELECT c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice, sum(l_quantity) FROM customer, orders, lineitem WHERE o_orderkey IN ( SELECT l_orderkey FROM lineitem l2 WHERE EXISTS ( SELECT 1 FROM orders o2 WHERE o2.o_orderkey = l2.l_orderkey AND o2.o_orderpriority IN ('1-URGENT', '2-HIGH') ) AND EXISTS ( SELECT 1 FROM partsupp ps WHERE ps.ps_partkey = l2.l_partkey AND ps.ps_suppkey = l2.l_suppkey AND ps.ps_availqty > 0 AND ps.ps_availqty > 100 AND EXISTS ( SELECT 1 FROM supplier s WHERE s.s_suppkey = ps.ps_suppkey AND s.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n, region r WHERE n.n_nationkey = s.s_nationkey AND n.n_regionkey = r.r_regionkey AND r.r_name = 'EUROPE' ) ) ) GROUP BY l_orderkey HAVING sum(l_quantity) > 300 ) AND c_custkey = o_custkey AND o_orderkey = l_orderkey AND c_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n, region r WHERE n.n_nationkey = c_nationkey AND n.n_regionkey = r.r_regionkey AND r.r_name IN ('EUROPE', 'AMERICA') ) AND EXISTS ( SELECT 1 FROM orders o3 WHERE o3.o_orderkey = l_orderkey AND o3.o_orderpriority IN ('1-URGENT', '2-HIGH') ) AND EXISTS ( SELECT 1 FROM partsupp ps2 WHERE ps2.ps_partkey = l_partkey AND ps2.ps_suppkey = l_suppkey AND ps2.ps_availqty > 0 AND ps2.ps_availqty > 100 AND EXISTS ( SELECT 1 FROM supplier s2 WHERE s2.s_suppkey = ps2.ps_suppkey AND s2.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n2, region r2 WHERE n2.n_nationkey = s2.s_nationkey AND n2.n_regionkey = r2.r_regionkey AND r2.r_name = 'EUROPE' ) ) ) GROUP BY c_name, c_custkey, o_orderkey, o_orderdate, o_totalprice ORDER BY o_totalprice DESC, o_orderdate
-- Q19
 SELECT SUM(l.l_extendedprice * (1 - l.l_discount)) AS revenue FROM lineitem l JOIN part p ON p.p_partkey = l.l_partkey JOIN orders o ON o.o_orderkey = l.l_orderkey AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') JOIN partsupp ps ON ps.ps_partkey = l.l_partkey AND ps.ps_suppkey = l.l_suppkey AND ps.ps_availqty > 100 JOIN supplier s ON s.s_suppkey = ps.ps_suppkey AND s.s_acctbal > 0 JOIN nation n ON n.n_nationkey = s.s_nationkey JOIN region r ON r.r_regionkey = n.n_regionkey AND r.r_name = 'EUROPE' WHERE l.l_shipmode IN ('AIR', 'AIR REG') AND l.l_shipinstruct = 'DELIVER IN PERSON' AND ( (p.p_brand = 'Brand#12' AND p.p_container IN ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG') AND l.l_quantity BETWEEN 1 AND 11 AND p.p_size BETWEEN 1 AND 5) OR (p.p_brand = 'Brand#23' AND p.p_container IN ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK') AND l.l_quantity BETWEEN 10 AND 20 AND p.p_size BETWEEN 1 AND 10) OR (p.p_brand = 'Brand#34' AND p.p_container IN ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG') AND l.l_quantity BETWEEN 20 AND 30 AND p.p_size BETWEEN 1 AND 15) ) 
-- Q20
 SELECT s.s_name, s.s_address FROM supplier s JOIN nation n ON n.n_nationkey = s.s_nationkey WHERE n.n_name = 'FRANCE' AND s.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM region r4 WHERE r4.r_regionkey = n.n_regionkey AND r4.r_name = 'EUROPE' ) AND EXISTS ( SELECT 1 FROM partsupp ps WHERE ps.ps_suppkey = s.s_suppkey AND ps.ps_availqty > 100 AND EXISTS ( SELECT 1 FROM part p WHERE p.p_partkey = ps.ps_partkey AND p.p_name LIKE '%ivory%' ) AND ps.ps_availqty > ( SELECT 0.5 * SUM(l.l_quantity) FROM lineitem l WHERE l.l_partkey = ps.ps_partkey AND l.l_suppkey = ps.ps_suppkey AND l.l_shipdate >= DATE '1995-01-01' AND l.l_shipdate < DATE '1995-01-01' + INTERVAL '1' year AND EXISTS ( SELECT 1 FROM orders o WHERE o.o_orderkey = l.l_orderkey AND o.o_orderpriority IN ('1-URGENT', '2-HIGH') ) AND EXISTS ( SELECT 1 FROM partsupp ps2 JOIN supplier s2 ON s2.s_suppkey = ps2.ps_suppkey JOIN nation n2 ON n2.n_nationkey = s2.s_nationkey JOIN region r2 ON r2.r_regionkey = n2.n_regionkey WHERE ps2.ps_partkey = l.l_partkey AND ps2.ps_suppkey = l.l_suppkey AND ps2.ps_availqty > 100 AND s2.s_acctbal > 0 AND r2.r_name = 'EUROPE' ) ) ) ORDER BY s.s_name 
-- Q21
SELECT s_name, count(*) AS numwait FROM supplier, lineitem l1, orders, nation WHERE s_suppkey = l1.l_suppkey AND o_orderkey = l1.l_orderkey AND o_orderstatus = 'F' AND l1.l_receiptdate > l1.l_commitdate AND EXISTS ( SELECT * FROM lineitem l2 WHERE l2.l_orderkey = l1.l_orderkey AND l2.l_suppkey <> l1.l_suppkey AND EXISTS ( SELECT 1 FROM orders o2 WHERE o2.o_orderkey = l2.l_orderkey AND o2.o_orderpriority IN ('1-URGENT', '2-HIGH') ) AND EXISTS ( SELECT 1 FROM partsupp ps WHERE ps.ps_partkey = l2.l_partkey AND ps.ps_suppkey = l2.l_suppkey AND ps.ps_availqty > 0 AND ps.ps_availqty > 100 AND EXISTS ( SELECT 1 FROM supplier s2 WHERE s2.s_suppkey = ps.ps_suppkey AND s2.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n2, region r2 WHERE n2.n_nationkey = s2.s_nationkey AND n2.n_regionkey = r2.r_regionkey AND r2.r_name = 'EUROPE' ) ) ) ) AND NOT EXISTS ( SELECT * FROM lineitem l3 WHERE l3.l_orderkey = l1.l_orderkey AND l3.l_suppkey <> l1.l_suppkey AND l3.l_receiptdate > l3.l_commitdate AND EXISTS ( SELECT 1 FROM orders o3 WHERE o3.o_orderkey = l3.l_orderkey AND o3.o_orderpriority IN ('1-URGENT', '2-HIGH') ) AND EXISTS ( SELECT 1 FROM partsupp ps2 WHERE ps2.ps_partkey = l3.l_partkey AND ps2.ps_suppkey = l3.l_suppkey AND ps2.ps_availqty > 0 AND ps2.ps_availqty > 100 AND EXISTS ( SELECT 1 FROM supplier s3 WHERE s3.s_suppkey = ps2.ps_suppkey AND s3.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n3, region r3 WHERE n3.n_nationkey = s3.s_nationkey AND n3.n_regionkey = r3.r_regionkey AND r3.r_name = 'EUROPE' ) ) ) ) AND s_nationkey = n_nationkey AND n_name = 'ARGENTINA' AND s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n4, region r4 WHERE n4.n_nationkey = s_nationkey AND n4.n_regionkey = r4.r_regionkey AND r4.r_name = 'EUROPE' ) AND EXISTS ( SELECT 1 FROM orders o4 WHERE o4.o_orderkey = l1.l_orderkey AND o4.o_orderpriority IN ('1-URGENT', '2-HIGH') ) AND EXISTS ( SELECT 1 FROM partsupp ps3 WHERE ps3.ps_partkey = l1.l_partkey AND ps3.ps_suppkey = l1.l_suppkey AND ps3.ps_availqty > 0 AND ps3.ps_availqty > 100 AND EXISTS ( SELECT 1 FROM supplier s4 WHERE s4.s_suppkey = ps3.ps_suppkey AND s4.s_acctbal > 0 AND EXISTS ( SELECT 1 FROM nation n5, region r5 WHERE n5.n_nationkey = s4.s_nationkey AND n5.n_regionkey = r5.r_regionkey AND r5.r_name = 'EUROPE' ) ) ) GROUP BY s_name ORDER BY numwait DESC, s_name
-- Q22
 WITH params AS ( SELECT ARRAY['13','31','23','29','30','18','17']::text[] AS codes, ARRAY['EUROPE','AMERICA']::text[] AS regions ), cust_region AS ( SELECT c.c_custkey, c.c_acctbal, substring(c.c_phone FROM 1 FOR 2) AS cntrycode FROM customer c JOIN nation n ON n.n_nationkey = c.c_nationkey JOIN region r ON r.r_regionkey = n.n_regionkey CROSS JOIN params p WHERE substring(c.c_phone FROM 1 FOR 2) = ANY (p.codes) AND r.r_name = ANY (p.regions) ), avg_bal AS ( SELECT avg(cr.c_acctbal) AS avg_acctbal FROM cust_region cr WHERE cr.c_acctbal > 0.0 ), no_orders AS ( SELECT cr.cntrycode, cr.c_acctbal FROM cust_region cr LEFT JOIN orders o ON o.o_custkey = cr.c_custkey CROSS JOIN avg_bal ab WHERE o.o_custkey IS NULL AND cr.c_acctbal > 0.0 AND cr.c_acctbal > ab.avg_acctbal ) SELECT cntrycode, count(*) AS numcust, sum(c_acctbal) AS totacctbal FROM no_orders GROUP BY cntrycode ORDER BY cntrycode 